import { Block, PoolsDropSelect } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Token } from '@cetus/types'
import { SingleCoinImage } from '@cetus/ui-kit'
import Icon from '@cetus/ui-kit/src/components/Icon'
import { cancelBubble, textEllipses } from '@cetus/utils'
import {
  Center,
  Flex,
  HStack,
  Popover,
  PopoverBody,
  PopoverContent,
  PopoverContentProps,
  PopoverTrigger,
  Text,
  useDisclosure
} from '@chakra-ui/react'
import { useEffect, useRef } from 'react'

interface SearchInputProps {
  selectCoinList: Token[]
  onClickSelectCoinList: (tokenInfo: Token) => void
  onDeleteSelectCoinList: (tokenInfo: Token) => void
  whiteTokenList?: Token[]
  isProfile?: boolean
  wrapStyle?: PopoverContentProps
  isSmall?: boolean
  setIsSmall?: (status: boolean) => void
  isVault?: boolean
}
export default function SearchInputBlock({
  whiteTokenList,
  selectCoinList,
  onClickSelectCoinList,
  onDeleteSelectCoinList,
  wrapStyle = { width: { base: 'calc(100vw - 20px)', lg: '292px' } },
  isSmall,
  setIsSmall,
  isVault,
  isProfile = false
}: SearchInputProps) {
  const { isApp } = useWindowWidth()
  const firstItemRef = useRef(null)
  const popoverRef = useRef<HTMLDivElement>(null)
  const { isOpen, onOpen, onClose } = useDisclosure()

  // 监听全局点击，关闭 Popover
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (isOpen && popoverRef.current && !popoverRef.current.contains(e.target as Node)) {
        onClose()
        if (selectCoinList.length == 0) {
          setIsSmall?.(true)
        }
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [isOpen, onClose, selectCoinList])

  useEffect(() => {
    if (isVault && selectCoinList.length == 0 && isApp) {
      onClose()
    }
  }, [isVault, selectCoinList])
  return (
    <div
      style={{
        width: '100%'
      }}
      ref={popoverRef}
    >
      <Popover
        isLazy
        placement="bottom-start"
        modifiers={[
          {
            name: 'flip',
            enabled: false // Disable automatic flip
          },
          {
            name: 'shift',
            enabled: false // Disable automatic shift
          }
        ]}
        initialFocusRef={firstItemRef}
        isOpen={isOpen}
        trigger="click"
        onClose={() => {
          onClose()
          if (selectCoinList.length == 0) {
            setIsSmall?.(true)
          }
        }}
        onOpen={onOpen}
      >
        <PopoverTrigger>
          <Center
            ref={firstItemRef}
            as="button"
            minW={{
              base: isProfile ? '100%' : isSmall ? '40px' : '100%',
              lg: '292px'
            }}
            width={{
              base: isSmall ? '40px' : '100%'
              // lg: '292px'
            }}
          >
            <Block
              cursor={selectCoinList.length >= 2 ? 'not-allowed' : 'pointer'}
              h="40px"
              borderRadius="12px"
              minW="100%"
              w="unset"
              p={!isSmall && isApp ? '0px 4px 0 10px' : '0px 4px 0 8px'}
              onClick={() => {
                setIsSmall?.(false)
                onOpen()
              }}
            >
              <HStack w={isSmall ? '40px' : '100%'} justify="space-between" h="100%" align="center">
                <Flex align="center" h="100%" w={isSmall ? '40px' : '100%'}>
                  <Icon xlinkHref="#icon-icon_search" svgHover="text_paragraph" />
                  {(!isSmall || !isApp) && (
                    <Text ml="4px" whiteSpace="nowrap">
                      {isApp && selectCoinList.length >= 2 ? '' : 'Filter by token'}
                    </Text>
                  )}
                </Flex>
                <HStack>
                  {selectCoinList?.map((item: Token) => {
                    return (
                      <HStack gap="4px" align="center" bg="button_ghost_bg" borderRadius="8px" p="5px 8px" key={item?.coin_type}>
                        <SingleCoinImage imageUrl={item?.logo_url} w="20px" h="20px" />
                        <Text ml="2px" color="text_caption">
                          {isApp ? textEllipses(item?.symbol || '', 5) : textEllipses(item?.symbol || '', 10)}
                        </Text>
                        <Icon
                          xlinkHref="#icon-icon_close"
                          onClick={(e: any) => {
                            cancelBubble(e)
                            onDeleteSelectCoinList(item)
                            onClose()
                          }}
                        />
                      </HStack>
                    )
                  })}
                </HStack>
              </HStack>
            </Block>
          </Center>
        </PopoverTrigger>
        {isOpen && selectCoinList?.length < 2 && (
          <PopoverContent
            w={{
              base: isProfile ? 'calc(100vw - 24px)' : 'calc(100vw - 68px)',
              lg: '292px'
            }}
            {...wrapStyle}
          >
            <PopoverBody p="0px">
              <PoolsDropSelect
                whiteTokenList={whiteTokenList}
                selectTokenList={selectCoinList}
                onDeleteToken={onDeleteSelectCoinList}
                onClickToken={onClickSelectCoinList}
                isVault={isVault}
              />
            </PopoverBody>
          </PopoverContent>
        )}
      </Popover>
    </div>
  )
}
