import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { HStack, Image, Text } from '@chakra-ui/react'

type VaultsTabProps = {
  text: string
  beforeLogo: string
  afterLogo: string
  isLST: boolean
  currentTab: any
  value: string
  onClickVaultsTab: (data: any) => void
  isShowSelect: boolean
}
export default function VaultsTab(props: VaultsTabProps) {
  const { beforeLogo, afterLogo, isLST, text, currentTab, value, onClickVaultsTab, isShowSelect = false } = props
  const { isApp } = useWindowWidth()
  return (
    <HStack
      p="10px 12px"
      bg={!isShowSelect ? (currentTab.value == value ? 'primary_opacity.10' : 'bg_secondary') : 'unset'}
      borderRadius="12px"
      border={isApp ? 'none' : '1px solid'}
      borderColor={currentTab.value == value ? 'primary' : 'border_secondary'}
      minHeight={!isShowSelect ? '42px' : 'auto'}
      cursor="pointer"
      userSelect="none"
      onClick={() => onClickVaultsTab({ label: text, value })}
      w={isApp && !isShowSelect ? '100%' : ''}
      role="group"
    >
      {beforeLogo && <Image width="20px" height="20px" src={beforeLogo} />}
      {afterLogo && <Image width="20px" height="20px" src={afterLogo} ml={isLST ? '-16px' : '0'} />}
      {isLST && (
        <Text
          bg="checked_bg"
          borderStyle="1px solid"
          borderColor="border_secondary"
          w="20px"
          h="20px"
          fontSize="10px"
          lineHeight="20px"
          textAlign="center"
          borderRadius="50%"
          ml="-16px"
          color="text_paragraph"
          fontWeight="500"
        >
          +2
        </Text>
      )}
      <Text color={!isShowSelect ? (currentTab.value == value ? 'primary' : 'text_paragraph') : 'text_caption'} _groupHover={{ color: 'primary' }}>
        {text}
      </Text>
    </HStack>
  )
}
